# -*- coding: utf-8 -*-
"""docs/21-决策记录机制与ADR出处核对.docx —— 22 点决策地图 21 号 ticket 的交付物。

内容全部来自 docs/决策记录规则.md、12 条 ADR 的出处行、以及 .scratch/session_digest.txt。
判断由 AI 做出，未经用户复核 —— 文档里逐处标明。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "21-决策记录机制与ADR出处核对.docx")


def main():
    doc = k.new_doc("21 决策记录机制 · v0.1 · 2026-11-05")

    k.title(
        doc,
        "决策记录机制与 12 条 ADR 出处核对",
        "22 点决策地图 · 21 号 ticket · 2026-11-05",
    )
    k.note(
        doc,
        "起因：0008 标着「用户裁定」，但用户说「我并没有决定这些」；2.1 里的信任阈值、比赛奖惩、战绩卡四行也是同样的来历。"
        "这份文档做两件事——立一条「只有用户点头才写进 ADR」的规矩，再把 12 条 ADR 逐条对回去。"
        "**下面所有「有出处 / 没出处」的判断都是 AI 做的，未经用户复核。**",
    )

    # ---------------- 一 ----------------
    k.h1(doc, "一", "机制：写 ADR 前先找出处")
    k.note(
        doc,
        "落在 `docs/决策记录规则.md`（10 行，可直接改）。要点：",
        spacer=False,
    )
    k.table(
        doc,
        ["什么时候写", "每条必带", "指不到出处怎么办"],
        [
            [
                "只有用户明确点头后才写 ADR；讨论中的、AI 提议的，留在 ticket 里，不进 `docs/adr/`",
                "**决定** / **日期** / **出处**（用户原话含日期或第几轮，或 ticket 号）/ **待确认项**",
                "头部写 `> 出处未确认`，文末写「依据：无记录 / 仅 AI 推断」，状态写 `待确认`；**不改决定内容**",
            ],
        ],
        [3.4, 6.6, 6.0],
        size=9,
        caption="表 1-1　三条主干；细则（编造被发现怎么处理、不删历史）见规则文件",
    )
    k.para(
        doc,
        "发现编造的处理：状态改成 `待确认`，或另写一条 `superseded` 覆盖旧的，**历史不删**。"
        "用户否认过的那条，正文保留，加一段注明「用户某日指出未决定，见 ticket NN」。",
        size=10,
    )

    # ---------------- 二 ----------------
    k.h1(doc, "二", "12 条 ADR 逐条核对")
    k.para(
        doc,
        "证据只有两处：`.scratch/session_digest.txt` 里的 267 轮用户消息，和 `git log`。"
        "「原话」栏只放能在记录里逐字找到的那句，找不到就写「无」。",
        size=10,
    )
    k.table(
        doc,
        ["#", "决定", "出处（用户原话，日期为 2026 年）", "结论"],
        [
            ["0001", "只交一个 `index.html`，不做后端", "无。来自平台硬约束 `research/hupu-aigame-platform.md`", "**未确认**"],
            ["0002", "不做比赛画面，比赛做成事件结算", "10-28「我们可以把比赛做成事件……不用处理经济、技能、AI、平衡」", "有出处"],
            ["0003", "段位只影响签约，不影响胜负", "10-31「段位只决定『能不能签约』」", "有出处"],
            ["0004", "胜负用 ÷50 并夹 5%–95%", "10-31 20:36 要求按公式做原型，同日 20:56「把这个公式应用到所有的比赛事件中」；**÷50 与 5%–95% 是 AI 提的数**", "有出处（数值待确认）"],
            ["0005", "钱买不到六维，也买不到胜负", "10-28「钱买不到比赛胜利，以及 6 维数值」", "有出处"],
            ["0006", "休息按体力上限的 25% 恢复", "11-04「把休息改为 25%」", "有出处"],
            ["0007", "行动成本随属性递增，收益固定 1 点", "11-04 选甲「递增 +3/10 点（从 40 起）」", "有出处"],
            ["0008", "比赛只给信任/人气/荣誉，不给属性", "无。用户 11-05 明确说「我并没有决定这些」", "**未确认**"],
            ["0009", "事件一周最多一个，先选后结算", "10-28「3 个行动 + 1 个事件」；**先选后结算用户没单独表过态**", "有出处（半条）"],
            ["0010", "存档结构一变就 +1，旧档作废", "无。用户只说过「每一个比赛周存一次，没有读档选项」", "**未确认**"],
            ["0011", "不设死线，用触发条件代替日期", "10-28「每个人节奏不同，不能算时间」；**推广到全部计划是 AI 做的**", "有出处（推断段）"],
            ["0012", "零位图、零音频", "只有「战绩卡纯文本四行」有原话（11-04）；零位图零音频没有", "**未确认**"],
        ],
        [1.2, 4.8, 7.6, 2.4],
        size=8.5,
        caption="表 2-1　有出处 8 条（0002–0007、0009、0011），没有出处 4 条（0001、0008、0010、0012）",
    )
    k.para(
        doc,
        "处理方式（已写进文件）：12 条都加了一行 `- 出处：`；4 条没有出处的，在标题下加 `> 出处未确认`，"
        "文末加一段「依据」。**任何一条的决定内容都没有改动。**",
        size=10,
    )

    # ---------------- 三 ----------------
    k.h1(doc, "三", "0008 单独说：只改状态，不改内容")
    k.table(
        doc,
        ["改了什么", "改成什么"],
        [
            ["元数据 `- 状态：`", "「用户裁定」→ **「待确认」**"],
            ["`> 出处未确认` + 文末「依据」", "已加"],
            ["新增 `## 待确认` 段", "「用户 2026-11-05 指出这条并未决定，见 ticket 03」"],
            ["正文（决定本身、理由、后果）", "**一字未改**"],
        ],
        [5.4, 10.6],
        size=9,
        caption="表 3-1　为什么保留正文：先留证据，再讨论要不要推翻",
    )

    # ---------------- 四 ----------------
    k.h1(doc, "四", "还需要你拍板的")
    k.table(
        doc,
        ["#", "要你定的事", "不定的后果"],
        [
            ["1", "表 2-1 里 8 条「有出处」是否认可（尤其 0004 的 ÷50、0009 的先选后结算、0011 的推广）", "出处是我判的；判错了这条 ADR 又变成「事实」"],
            ["2", "`docs/build/build_4_4.py` 会按内置文案重生成这 12 个文件，一跑就覆盖这次的出处行——改脚本，还是以后不再跑它", "下次重跑，出处标注静默消失"],
            ["3", "`docs/4.4-决策记录.docx` 第二节仍写着 0008 是「用户裁定」、0002/0005/0012 有用户明确表态，与新结论冲突", "两份文档互相打脸"],
            ["4", "0008 本身往哪走（比赛到底给什么），归 ticket 03，不在这条里定", "奖励结构继续悬着"],
        ],
        [0.9, 8.1, 7.0],
        size=9,
        caption="表 4-1　前三条是这次新暴露的，第四条原有",
    )
    k.note(
        doc,
        "本机制按默认方案起草执行，**未经用户确认**。规则文件第一行已写明这一点。",
    )

    doc.save(OUT)
    print("saved:", OUT)


if __name__ == "__main__":
    main()
